DO $$ DECLARE d text; BEGIN SELECT pg_get_constraintdef(oid) INTO STRICT d FROM pg_constraint WHERE conrelid='cmd_command'::regclass AND conname='cmd_command_command_type_check'; ALTER TABLE cmd_command DROP CONSTRAINT cmd_command_command_type_check; EXECUTE format('ALTER TABLE cmd_command ADD CONSTRAINT cmd_command_command_type_check %s',replace(d,'CHECK (','CHECK (command_type=''resolve_steward_service'' OR ')); END $$;
CREATE TABLE cmd_steward_service_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),journey_id bigint NOT NULL,steward_actor_id bigint NOT NULL,passenger_actor_id bigint NOT NULL,service_rule_id bigint NOT NULL,service_code text NOT NULL,service_reference text NOT NULL CHECK(btrim(service_reference)<>''),passage_class text NOT NULL CHECK(passage_class='high'),task_command_id bigint NOT NULL UNIQUE REFERENCES cmd_actor_task_receipt(command_id),check_total smallint NOT NULL,effect smallint NOT NULL,succeeded boolean NOT NULL,FOREIGN KEY(journey_id,campaign_id) REFERENCES journey_journey(journey_id,campaign_id),FOREIGN KEY(steward_actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(passenger_actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(service_rule_id,service_code) REFERENCES rule_steward_service(rule_id,service_code),CHECK(steward_actor_id<>passenger_actor_id));
